cd "C:/Users/admin/AppData/Local/Temp/wps-windows-check/20261018T140444Z-4b263d9-eval/run-3/convert-markdown-to-docx" && python -I -c "
import zipfile,sys
z=zipfile.ZipFile('guide.docx')
for n in z.namelist():
    if 'media' in n: print(n, z.getinfo(n).file_size)
"

Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead("C:\Users\admin\AppData\Local\Temp\wps-windows-check\20261018T140444Z-4b263d9-eval\run-3\convert-docx-to-pptx\brief.pptx")
$slides = $zip.Entries | Where-Object { $_.FullName -match '^ppt/slides/slide\d+\.xml$' } | Sort-Object FullName
"slide_count=$($slides.Count)"
$pres = $zip.Entries | Where-Object { $_.FullName -eq 'ppt/presentation.xml' }
$sr = New-Object System.IO.StreamReader($pres.Open())
$xml = $sr.ReadToEnd(); $sr.Close()
if ($xml -match '<p:sldSz[^>]*>') { $Matches[0] }
foreach ($s in $slides) {
  $r = New-Object System.IO.StreamReader($s.Open()); $d = $r.ReadToEnd(); $r.Close()
  $texts = [regex]::Matches($d,'<a:t>([^<]*)</a:t>') | ForEach-Object { $_.Groups[1].Value }
  "$($s.FullName): " + ($texts -join ' | ').Substring(0, [Math]::Min(120, ($texts -join ' | ').Length))
}
$zip.Dispose()
